sys_script_include.script:
/* global Class, GlideRecord, GlideTableHierarchy, GlideScopedEvaluator */
/* eslint no-undef: "error" */
var ScriptExecutor = Class.create();
ScriptExecutor.prototype = {
	initialize: function () {
		this.accessableTables = this._getAccessableTables();
	},

	_getAccessableTables: function () {
		const tableGr = new GlideRecord('sys_db_object');
		tableGr.addNullQuery('access').addOrCondition('access', 'public');
		tableGr.addQuery('update_access', true);
		tableGr.addQuery('name', 'IN', new GlideTableHierarchy('sys_metadata').getTableExtensions());
		tableGr.addQuery();
		tableGr.setLimit(10000);
		tableGr.query();

		const accessableTables = {};
		while (tableGr.next()) {
			const tabelName = tableGr.name.toString();
			const dictGr = new GlideRecord('sys_dictionary');
			dictGr.addQuery('internal_type', 'script');
			dictGr.addQuery('name', tabelName);
			dictGr.addNotNullQuery('element');
			dictGr.setLimit(1);
			dictGr.query();
			if (dictGr.next()) {
				accessableTables[tabelName] = dictGr.getValue('element');
			}
		}

		return accessableTables;
	},

	_getInfusableScript: function (scope) {
		const scriptGr = new GlideRecord('sys_metadata');
		scriptGr.addQuery('sys_scope', scope);
		scriptGr.addQuery('sys_class_name', 'IN', Object.keys(this.accessableTables));
		scriptGr.setLimit(1);
		scriptGr.query();
		if (scriptGr.next()) {
			// does not trigger a cross scope privilege access btw (lol!)
			return scriptGr.getElement('ref_' + scriptGr.sys_class_name).getRefRecord();
		}

		return null;
	},

	canExecute: function (scope) {
		return this._getInfusableScript(scope) != null;
	},

	executeScript: function (scope, script, paramMap = {}) {
		const result = {
			status: 'error'
		};

		const scriptGr = this._getInfusableScript(scope);
		if (!scriptGr) {
			result.message = 'Selected scope does not have a infusable script record' + scope;
			return result;
		}

		const gse = new GlideScopedEvaluator();
		for (const [key, value] of Object.entries(paramMap)) {
			gse.putVariable(key, value);
		}

		result.status = 'success';

		const field = this.accessableTables[scriptGr.getRecordClassName()];
		scriptGr[field] = script;
		result.script_result = gse.evaluateScript(scriptGr, field);
		return result;
	},

	type: 'ScriptExecutor'
};
